// 原实现用 parse(home).root（即文件系统根 "/"）作为上溯边界，一路 fsync 所有祖先。
// 桌面 Linux 上没问题，但 Android 的 /data/user/0 是全部应用的父目录，
// 普通应用无权访问 —— 遍历到那一级必然 EACCES，附件保存全线失败。
// 这里把边界收到应用包目录（DSH_HOME 的上两级），再往上都不是本应用的地盘。
const boundary = process.platform === "android"
	? dirname(dirname(home))
	: parse(home).root;
await ensureDurableDirectory(home, boundary);

// Android 10+ 禁止普通应用创建硬链接（link 直接 EACCES）。
// 此处是为「已存在的不可变对象」再挂一个别名，语义上不能用 rename（会把源移走），
// 故退化为复制：内容逐字节相同，读取侧完全透明。
if (process.platform === "android") {
	await copyFile(source, target);
} else {
	await link(source, target);
}

// 同上：Android 禁硬链接。这里 staged 是一次性临时文件，
// rename 的语义与 link 完全等价（都是把内容落到 target）。
if (process.platform === "android") {
	await rename(staged.path, target);
} else {
	await link(staged.path, target);
}

// 桌面走 link：提交后 staged.path 仍有一个目录项，这里的清理是"删掉多余的名字"。
// Android 走 rename：源目录项已被移走，裸 unlink 必然 ENOENT —— 而它不是
// AttachmentError，会被外层 catch 包成 ATTACHMENT_WRITE_FAILED，
// 于是"对象其实已正确落盘"却报失败，chmod 与目录 fsync 也一并被跳过。
// removeTemporary 只吞 ENOENT、其余照抛，正是这里需要的语义。
await removeTemporary(staged.path);

// 原实现把所有非附件异常都归到 agent-busy，真实原因只藏在 reason 里，
// 而前端只渲染 message —— 用户永远只看到"会话忙"，完全无法定位。
// 这里把原始错误带进 message，让失败原因直接可见。
throw new RemoteError("session/agent-busy", "prompt rejected: " + (error && error.message ? error.message : String(error)), { reason: String(error) });

// Android 10+ 禁止普通应用创建硬链接，link() 会直接 EACCES。
// 先用 lstat 保留"目标已存在则返回 false"的语义，再用 rename 原子发布。
if (internals.platform === "android") {
	try {
		await internals.fs.lstat(currentPath);
		return false;
	} catch {
		// 目标不存在，可以发布
	}
	await internals.fs.rename(staged, currentPath);
	await syncDirectory(dirname(currentPath), internals);
	return true;
}
try {
	await internals.fs.link(staged, currentPath);

// Android 10+ 禁止普通应用创建硬链接，link() 会直接 EACCES，进而让整个会话
// 持久化失败（实测报错：EACCES: permission denied, link '...tmp' -> '...jsonl.zstd'）。
// 这里退化为 rename：同样是原子替换，只是失去了 link 自带的"拒绝覆盖已存在文件"
// 这一层原子保证 —— 上游 rejectExistingLog 已做前置存在性检查，接受该弱化。
if (process.platform === "android") {
	await rename(tmp, finalPath);
} else {
	await link(tmp, finalPath);
}

// Android 10+ 禁止普通应用创建硬链接，link() 会直接 EACCES。
// 先用 lstat 保留"目标已存在则返回 false"的语义，再用 rename 原子发布。
if (internals.platform === "android") {
	try {
		await internals.fs.lstat(currentPath);
		return false;
	} catch {
		// 目标不存在，可以发布
	}
	await internals.fs.rename(staged, currentPath);
	await syncDirectory(dirname(currentPath), internals);
	return true;
}
try {
	await internals.fs.link(staged, currentPath);

// Android 10+ 在 SELinux 层禁止 untrusted_app 创建硬链接（实测同目录 ln 亦 EACCES），
// 而 link() 正是"新建文件"这条路的唯一提交手段 —— 结果是 write 工具任何落盘都失败。
// 这里手工复现 link 的 EEXIST 语义后改用 rename：同为原子替换，
// 且不破坏 createIfAbsent"目标已存在即失败"的约定。
if (platform === "android") {
	let exists = true;
	try {
		await lstat(absolutePath);
	} catch (error) {
		if (isENOENT(error)) exists = false;
		else throw error;
	}
	if (exists) {
		const conflict = new Error(`EEXIST: file already exists, link '${tempPath}' -> '${absolutePath}'`);
		conflict.code = "EEXIST";
		conflict.errno = -17;
		conflict.syscall = "link";
		conflict.path = absolutePath;
		throw conflict;
	}
	await rename(tempPath, absolutePath);
} else {
	await linkFile(tempPath, absolutePath);
}

// Android 的 Node 是 Linux ABI，但 process.platform 是 'android'，
// 而 @vscode/ripgrep 按平台拼包名（optionalDependencies 里没有 android 变体），
// 会抛 "Could not find @vscode/ripgrep-android-arm64"，令 glob/grep 完全不可用。
// 这里直接解析随包分发的 linux-<arch> 二进制，绕开它的平台拼名。
if (process.platform === "android") {
	const { createRequire } = await import("node:module");
	const manifest = createRequire(import.meta.url)
		.resolve(`@vscode/ripgrep-linux-${process.arch}/package.json`);
	const rg = join(parse(manifest).dir, "bin", "rg");
	// 兜底补可执行位：zip 在 Windows 上打包不带 Unix mode，解压后常是 600，
	// spawn 会直接 EACCES（表现为 "ripgrep provider failure"）。
	// App 侧解压器已经会补，这里再保一道 —— 换打包机或重装时不会复发。
	try {
		const { chmod } = await import("node:fs/promises");
		await chmod(rg, 0o755);
	} catch {
		// 已可执行、或文件系统不允许改：交给 spawn 自己报错，别在这里吞掉真正的失败
	}
	return rg;
}
const dependency = (await import("@vscode/ripgrep")).rgPath;

// 原实现恒以 homedir() 作为浏览起点。
// 但 Android 上 HOME 必须指向应用私有目录（公共存储是 FUSE，不支持 symlink，
// profile 引导会卡死启动），于是选择器被锁死在私有区：
// 用户既看不到公共目录，停在起点直接点"打开"还会把工作区设成私有 HOME 本身，
// 导致 Agent 的产出永远拿不到。
// 允许用环境变量覆盖起点 —— App 侧会把它指向公共工作区。
const home = process.env.DSH_PICKER_ROOT || homedir();

const { arch } = process;
// Android 的 Node 运行时是 Linux ABI（Termux 构建），flock() 由 bionic 提供，
// 预编译产物也用 linux-arm64 那一份。原实现只认字面量 'linux'/'darwin'，
// 于是 Android 上一律抛 ERR_FLOCK_UNSUPPORTED_PLATFORM，会话持久化直接失败。
const platform = process.platform === 'android' ? 'linux' : process.platform;

// Android 上直接放行。
// 该包的两份预编译产物都无法在 bionic 上加载：musl 版缺 __errno_location
// （bionic 不提供该符号，实测 dlopen 失败），glibc 版依赖 glibc 同样不可用。
// 而本应用内只跑一个 dsh 进程，会话文件不存在并发写 —— 少一层文件锁，
// 远好过让整个会话因加锁失败而跑不起来。
if (process.platform === 'android') {
    return;
}
